// Copies the files in public/ into src/static.generated.ts so the Worker can
// serve them itself. Runs automatically before dev, deploy, tests and
// typecheck; the generated file is never edited or committed.
import { readFileSync, readdirSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const TYPES = { ".css": "text/css; charset=utf-8", ".js": "text/javascript; charset=utf-8" };

export function embedStatic() {
  const publicDir = path.join(root, "public");
  const files = {};
  for (const entry of readdirSync(publicDir, { recursive: true, withFileTypes: true })) {
    if (!entry.isFile()) continue;
    const absolute = path.join(entry.parentPath, entry.name);
    const type = TYPES[path.extname(entry.name)];
    if (!type) throw new Error(`No content type known for ${absolute}`);
    const urlPath = "/" + path.relative(publicDir, absolute).split(path.sep).join("/");
    files[urlPath] = { type, body: readFileSync(absolute, "utf8") };
  }
  const sorted = Object.fromEntries(Object.entries(files).sort(([a], [b]) => a.localeCompare(b)));
  const source =
    "// Generated by scripts/embed-static.mjs from public/. Do not edit.\n" +
    `export const STATIC_FILES: Record<string, { type: string; body: string }> = ${JSON.stringify(sorted, null, 2)};\n`;
  writeFileSync(path.join(root, "src/static.generated.ts"), source);
  return Object.keys(sorted);
}

// Vitest calls the default export as its global setup step.
export default function setup() {
  embedStatic();
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  console.log(`embedded ${embedStatic().length} static files`);
}
